#define MAXN 200005

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *graph[MAXN];
int visited[MAXN];

void add_edge(int u, int v) {
    Edge *e = malloc(sizeof(Edge));
    e->to = v;
    e->next = graph[u];
    graph[u] = e;
}

int dfs(int u) {
    visited[u] = 1;
    int g = 0;
    for (Edge *e = graph[u]; e; e = e->next) {
        int v = e->to;
        if (!visited[v]) {
            g ^= (dfs(v) + 1);
        }
    }
    return g;
}

