#include <stdio.h>
#include <stdlib.h>

typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        puts("Bob");
        return 0;
    }

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);

        edges[ecnt].to = y;
        edges[ecnt].next = head[x];
        head[x] = ecnt++;
        deg[x]++;

        edges[ecnt].to = x;
        edges[ecnt].next = head[y];
        head[y] = ecnt++;
        deg[y]++;
    }

    /* Root the tree at 1 and compute parents iteratively */
    int *parent = (int *)calloc(N + 1, sizeof(int));
    int *order = (int *)malloc(sizeof(int) * N);
    int *stack = (int *)malloc(sizeof(int) * N);

    int top = 0, ord = 0;
    stack[top++] = 1;
    parent[1] = -1;

    while (top) {
        int v = stack[--top];
        order[ord++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;
            parent[u] = v;
            stack[top++] = u;
        }
    }

    /* Grundy:
       g(v) = xor over children u of (g(u) + 1)
       First player wins iff g(1) != 0
    */
    int *grundy = (int *)calloc(N + 1, sizeof(int));

    for (int i = N - 1; i >= 0; i--) {
        int v = order[i];
        int x = 0;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;
            x ^= (grundy[u] + 1);
        }
        grundy[v] = x;
    }

    puts(grundy[1] ? "Alice" : "Bob");

    free(edges);
    free(head);
    free(deg);
    free(parent);
    free(order);
    free(stack);
    free(grundy);

    return 0;
}

