        g[x].push_back(y);
        g[y].push_back(x);
    }

    // Root the tree at 1 and compute Grundy number:
    // g(v) = xor over children u of (g(u) + 1)
    vector<int> parent(N + 1, 0), order;
    order.reserve(N);

    stack<int> st;
    st.push(1);
    parent[1] = -1;

    while (!st.empty()) {
        int v = st.top();
        st.pop();
        order.push_back(v);
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            parent[to] = v;
            st.push(to);
        }
    }

    vector<int> grundy(N + 1, 0);

    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int v = order[i];
        int x = 0;
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            x ^= (grundy[to] + 1);
        }
        grundy[v] = x;
    }

    cout << (grundy[1] ? "Alice" : "Bob") << '\n';
    return 0;
