public class Main {
    static List<Integer>[] g;
    static int[] parent;
    static int[] order;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            g[x].add(y);
            g[y].add(x);
        }

        if (N == 1) {
            System.out.println("Bob");
            return;
        }

        parent = new int[N + 1];
        order = new int[N];
        int idx = 0;

        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dq.add(1);
        parent[1] = -1;

        while (!dq.isEmpty()) {
            int v = dq.poll();
            order[idx++] = v;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                dq.add(to);
            }
        }

        int[] grundy = new int[N + 1];

        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            int x = 0;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                x ^= (grundy[to] + 1);
            }
            grundy[v] = x;
        }

        System.out.println(grundy[1] != 0 ? "Alice" : "Bob");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

