            int x = Integer.parseInt(st.nextToken()), y = Integer.parseInt(st.nextToken());
            adj[x].add(y); adj[y].add(x);
        }
        int grundy = dfs(1, 0);
        System.out.println(grundy != 0 ? "Alice" : "Bob");
    }

    static int dfs(int v, int parent) {
        int xorVal = 0;
        for (int u : adj[v]) {
            if (u != parent) xorVal ^= (dfs(u, v) + 1);
        }
        return xorVal;
    }
