import sys
sys.setrecursionlimit(300000)

def solve():
    input = sys.stdin.readline
    n = int(input())
    g = [[] for _ in range(n)]
    for _ in range(n - 1):
        x, y = map(int, input().split())
        g[x-1].append(y-1)
        g[y-1].append(x-1)

    visited = [False] * n
    parent = [-1] * n
    order = [0]
    visited[0] = True
    for v in order:
        for to in g[v]:
            if not visited[to]:
                visited[to] = True
                parent[to] = v
                order.append(to)

    size = [0] * n
    for v in reversed(order):
        s = 1
        for to in g[v]:
            if to != parent[v]:
                s += size[to]
        size[v] = s

    for v in range(1, n):
        if parent[v] == 0:
            if size[v] % 2 == 1:
                print("Alice")
                return
    print("Bob")

if __name__ == "__main__":
    solve()
